"""policy.ini (docs/policy.md)."""

import re
from datetime import timedelta, timezone
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

BUILTIN = {"max_size": None, "max_age": None, "naming": "numbered", "offset": timezone.utc,
           "compress_after": 1, "keep": 5, "keep_days": None}
KEYS = set(BUILTIN)
_UNITS = {"K": 1024, "M": 1024 ** 2, "G": 1024 ** 3}


def _bad(msg):
    raise DataError("policy", f"policy.ini: {msg}")


def _num(v, minimum):
    if not re.fullmatch(r"[0-9]+", v) or int(v) < minimum:
        _bad(f"bad number {v!r}")
    return int(v)


def _value(key, v):
    if key == "max_size":
        if v == "off":
            return None
        m = re.fullmatch(r"([0-9]+)([KMGkmg]?)", v)
        if not m:
            _bad(f"bad size {v!r}")
        return int(m.group(1)) * _UNITS.get(m.group(2).upper(), 1)
    if key == "max_age":
        if v == "off":
            return None
        m = re.fullmatch(r"([0-9]+)([mhd])", v)
        if not m:
            _bad(f"bad duration {v!r}")
        return timedelta(**{{"m": "minutes", "h": "hours", "d": "days"}[m.group(2)]: int(m.group(1))})
    if key == "naming":
        if v not in ("numbered", "dated"):
            _bad(f"bad naming {v!r}")
        return v
    if key == "offset":
        m = re.fullmatch(r"([+-])([0-9]{2}):([0-9]{2})", v)
        if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
            _bad(f"bad offset {v!r}")
        d = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
        return timezone(-d if m.group(1) == "-" else d)
    if key == "compress_after":
        return _num(v, 0)
    if key == "keep":
        return _num(v, 1)
    if key == "keep_days":
        return None if v == "off" else _num(v, 1)


class Policy:
    def __init__(self, defaults, sections):
        self.defaults = defaults
        self.sections = sections

    def get(self, name: str) -> dict:
        out = dict(BUILTIN)
        out.update(self.defaults)
        out.update(self.sections.get(name, {}))
        return out

    def names(self):
        return set(self.sections)


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"policy.ini: {e}") from None
    defaults, sections, cur, seen = {}, {}, None, set()
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                _bad(f"bad line {line!r}")
            title = line[1:-1]
            if title == "defaults":
                target = defaults
            elif title.startswith("stream ") and streams.valid(title[7:]):
                target = sections.setdefault(title[7:], {})
            else:
                _bad(f"unknown section {title!r}")
            if title in seen:
                _bad(f"section {title!r} twice")
            seen.add(title)
            cur, keys = target, set()
            continue
        if cur is None or "=" not in line:
            _bad(f"bad line {line!r}")
        k, v = (s.strip() for s in line.split("=", 1))
        if k not in KEYS:
            _bad(f"unknown key {k!r}")
        if k in keys:
            _bad(f"key {k!r} twice")
        keys.add(k)
        cur[k] = _value(k, v)
    return Policy(defaults, sections)
