"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy as policy_mod, state as state_mod, streams
from logkeep.errors import DataError, Refused

_OLD = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")
_DAY = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})\Z")


def parse_time(v):
    """A time of data.md section 2 as an aware datetime, or None."""
    if not isinstance(v, str):
        return None
    try:
        if _OLD.match(v):
            return datetime.strptime(v, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
        t = datetime.fromisoformat(v)
    except ValueError:
        return None
    return t if t.tzinfo is not None else None


def _validate_state(doc, existing):
    for name in existing:
        entry = doc["streams"].get(name)
        if entry is None:
            continue
        if "opened" in entry and parse_time(entry["opened"]) is None:
            raise DataError("state", f"{name}: bad opened")
        if "archives" in entry:
            arch = entry["archives"]
            if not isinstance(arch, dict):
                raise DataError("state", f"{name}: archives is not an object")
            for k, v in arch.items():
                if parse_time(v) is None:
                    raise DataError("state", f"{name}: bad time for {k}")
        if "rotations" in entry:
            r = entry["rotations"]
            if isinstance(r, bool) or not isinstance(r, int) or r < 0:
                raise DataError("state", f"{name}: bad rotations")


def _find_archives(files, name, naming):
    """Returns list of dicts with key, name, gz, sorted newest first."""
    if naming == "numbered":
        rx = re.compile(re.escape(name) + r"\.log\.([1-9][0-9]*)(\.gz)?\Z")
    else:
        rx = re.compile(re.escape(name) + r"\.log\.([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z")
    out, places = [], {}
    for f in files:
        m = rx.match(f)
        if not m:
            continue
        if naming == "numbered":
            key, gz = (int(m.group(1)),), bool(m.group(2))
        else:
            dm = _DAY.match(m.group(1))
            try:
                day = date(int(dm.group(1)), int(dm.group(2)), int(dm.group(3)))
            except ValueError:
                continue
            key, gz = (day, int(m.group(2)) if m.group(2) else 1), bool(m.group(3))
        if key in places:
            raise DataError("archives", f"{places[key]} and {f} are in the same place")
        places[key] = f
        out.append({"key": key, "old": f, "gz": gz})
    out.sort(key=lambda a: a["key"], reverse=True)
    return out


def _stem(a):
    return a["old"][:-3] if a["gz"] else a["old"]


def run(ctx, requested, dry_run, force):
    logs = streams.logs_dir(ctx.data)
    pol = policy_mod.load(ctx.policy_path)
    files = sorted(p.name for p in logs.iterdir() if p.is_file()) if logs.is_dir() else []
    existing = set(streams.active(ctx.data)) | pol.names()
    doc = ctx.state
    _validate_state(doc, existing)
    if requested:
        for n in requested:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
        names = sorted(set(requested))
    else:
        names = sorted(existing)
    plans = {n: _find_archives(files, n, pol.get(n)["naming"]) for n in names}

    now = ctx.now
    out, ops_remove, ops_move, new_entries = [], [], [], {}
    n_rot = n_rem = n_comp = 0
    for name in names:
        p = pol.get(name)
        entry = doc["streams"].get(name, {})
        arch = plans[name]
        log = streams.log_path(ctx.data, name)
        what = None
        if not log.is_file():
            what = "no log"
        else:
            size = log.stat().st_size
            if size == 0:
                what = "empty"
            elif force:
                what = "rotate (forced)"
            elif p["max_size"] is not None and size >= p["max_size"]:
                what = "rotate (size)"
            else:
                if p["max_age"] is not None:
                    opened = parse_time(entry.get("opened")) if "opened" in entry else None
                    if opened is None and "opened" not in entry:
                        with log.open("rb") as f:
                            first = f.readline().decode("utf-8", "replace").rstrip("\r\n")
                        opened = parse_time(first.split(" ", 1)[0])
                    if opened is not None and now - opened >= p["max_age"]:
                        what = "rotate (age)"
            if what is None:
                what = "not due"
        rotated = what.startswith("rotate")
        times = dict(entry.get("archives", {}))

        for a in arch:
            a["new"] = False
        if rotated:
            if p["naming"] == "numbered":
                key = (float("inf"),)
                newname = f"{name}.log.0"
            else:
                day = now.astimezone(p["offset"]).date()
                ks = [a["key"][1] for a in arch if a["key"][0] == day]
                k = max(ks) + 1 if ks else 1
                newname = f"{name}.log.{day.isoformat()}" + (f".{k}" if k > 1 else "")
                key = (day, k)
            arch.insert(0, {"key": key, "old": None, "gz": False, "new": True, "stem": newname})
            if p["naming"] == "dated":
                arch.sort(key=lambda a: a["key"], reverse=True)
            times_new = stamp = dates.stamp(now)
        # retention
        kept, removed = [], []
        for i, a in enumerate(arch, 1):
            drop = i > p["keep"]
            if not drop and p["keep_days"] is not None and not a["new"] and a["old"] in times:
                if now - parse_time(times[a["old"]]) >= timedelta(days=p["keep_days"]):
                    drop = True
            (removed if drop else kept).append(a)
        lines = [f"{name}: {what}"]
        new_state = {}
        for i, a in enumerate(kept, 1):
            stem = a["stem"] if a["new"] else _stem(a)
            if p["naming"] == "numbered":
                stem = f"{name}.log.{i}"
            comp = i > p["compress_after"] and not a["gz"]
            final = stem + (".gz" if a["gz"] or comp else "")
            if comp:
                n_comp += 1
            if a["new"]:
                lines.append(f"  new {final}")
                new_state[final] = stamp
                ops_move.append((name + ".log", final, comp, True))
            else:
                lines.append(f"  {final} <- {a['old']}" if final != a["old"] else f"  {final}")
                if a["old"] in times:
                    new_state[final] = times[a["old"]]
                if final != a["old"]:
                    ops_move.append((a["old"], final, comp, False))
        for a in removed:
            if a["new"]:
                raise AssertionError("new archive removed")
            lines.append(f"  remove {a['old']}")
            ops_remove.append(a["old"])
        out.extend(lines)
        n_rem += len(removed)
        n_rot += rotated
        e = {}
        if rotated:
            e["opened"] = stamp
        elif "opened" in entry:
            e["opened"] = entry["opened"]
        e["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        e["archives"] = new_state
        new_entries[name] = e
    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    for old in ops_remove:
        (logs / old).unlink()
    staged = []
    for i, (old, final, comp, is_active) in enumerate(ops_move):
        tmp = logs / f".logkeep-tmp-{i}"
        (logs / old).rename(tmp)
        if is_active:
            (logs / old).write_bytes(b"")
        staged.append((tmp, logs / final, comp))
    for tmp, final, comp in staged:
        if comp:
            final.write_bytes(gzip.compress(tmp.read_bytes(), mtime=0))
            tmp.unlink()
        else:
            tmp.rename(final)
    doc["streams"].update(new_entries)
    state_mod.save(ctx.state_path, doc)
    return out
